window.CH_LEARN_NCERT = {"c7maths_0": {"learn": [{"icon": "🔢", "title": "Lakhs and Crores", "text": "In the Indian system, 1 lakh = 1,00,000 and 1 crore = 1,00,00,000 (100 lakh).", "example": "The population of a small city may be about 12,50,000 (twelve lakh fifty thousand).", "dyk": "10 lakh make 1 million in the international system.", "real": "Prices of houses and cars in India are often said in lakhs."}, {"icon": "🌍", "title": "Indian vs International System", "text": "The Indian system groups digits as 3, then 2, 2... from the right; the international system groups in threes.", "example": "45,67,890 (Indian) is written 4,567,890 (international).", "dyk": "1 crore = 10 million, and 100 crore = 1 billion.", "real": "News about world population uses millions and billions."}, {"icon": "📏", "title": "Reading Large Numbers", "text": "Read a large number group by group, using the place name of each group.", "example": "3,05,00,200 is read as three crore five lakh two hundred.", "dyk": "A zero in a place means that place has nothing in it, but it still keeps the other digits in position.", "real": "Cheques require the amount to be written in words."}, {"icon": "⚖️", "title": "Comparing Large Numbers", "text": "The number with more digits is larger; if digits are equal, compare from the leftmost digit.", "example": "7,89,000 > 7,87,999 because 9 thousands > 7 thousands in the first place they differ.", "dyk": "Writing numbers in a column helps compare place by place.", "real": "Comparing the populations of states uses this skill."}, {"icon": "🎯", "title": "Estimation", "text": "Rounding large numbers to the nearest thousand, lakh or crore gives a quick estimate.", "example": "4,78,345 rounded to the nearest lakh is 5,00,000.", "dyk": "Estimates are useful when exact numbers are not needed or not known.", "real": "Organisers estimate the crowd at a cricket match."}], "revision": {"terms": [["Lakh", "1,00,000 (one hundred thousand)"], ["Crore", "1,00,00,000 (ten million)"], ["Million", "10,00,000 in the Indian system"], ["Place value", "Value of a digit due to its position"], ["Estimation", "Finding an approximate value by rounding"]], "facts": ["1 crore = 100 lakh = 10 million.", "1 lakh = 100 thousand.", "Rounding helps make quick estimates."]}, "summary": "Large numbers in India are read in thousands, lakhs and crores, while the international system uses thousands, millions and billions. Reading, writing and comparing numbers depends on place value. Rounding to the nearest thousand, lakh or crore helps estimate quickly."}, "c7maths_1": {"learn": [{"icon": "🧮", "title": "What is an Expression?", "text": "An arithmetic expression is a combination of numbers and operations, like 13 + 2 × 6.", "example": "The value of 30 − 5 × 4 is 10.", "dyk": "Two different expressions can have the same value, like 10 + 2 and 6 × 2.", "real": "A shop bill is an expression: items' prices added together."}, {"icon": "➕", "title": "Terms in an Expression", "text": "Terms are the parts of an expression that are added. A minus sign belongs to the term after it.", "example": "In 25 − 6 × 2 + 4, the terms are 25, −6 × 2 and 4.", "dyk": "Adding terms in any order gives the same result.", "real": "Splitting a bill into parts uses terms."}, {"icon": "🎛️", "title": "Brackets", "text": "Brackets tell us which part to calculate first.", "example": "(5 + 3) × 2 = 16, but 5 + 3 × 2 = 11.", "dyk": "Brackets can change the value of an expression completely.", "real": "Calculators follow the same order rules."}, {"icon": "🔁", "title": "Swapping and Grouping", "text": "Addition and multiplication can be done in any order and grouped in any way without changing the value.", "example": "27 + 48 + 73 = (27 + 73) + 48 = 148.", "dyk": "Smart grouping makes mental maths faster.", "real": "Adding prices that make round hundreds is quicker."}, {"icon": "🧩", "title": "Distributive Property", "text": "Multiplying a sum is the same as multiplying each part and adding: a × (b + c) = a × b + a × c.", "example": "6 × 104 = 6 × 100 + 6 × 4 = 624.", "dyk": "This is why 99 × 7 = 700 − 7 = 693.", "real": "Shopkeepers use it to multiply quickly in their heads."}], "revision": {"terms": [["Expression", "Numbers joined with operations"], ["Term", "A part of an expression that is added"], ["Value", "The result after calculating an expression"], ["Brackets", "Show which operation to do first"], ["Distributive property", "a × (b + c) = a × b + a × c"]], "facts": ["Multiplication and division are done before addition and subtraction.", "Brackets are solved first.", "Changing the order of addition does not change the sum."]}, "summary": "An arithmetic expression combines numbers with operations, and its value is found by following an order: brackets first, then multiplication and division, then addition and subtraction. Expressions can be broken into terms. Swapping, grouping and the distributive property help calculate quickly."}, "c7maths_2": {"learn": [{"icon": "🔍", "title": "Tenths and Hundredths", "text": "When one unit is divided into 10 equal parts, each part is one tenth (0.1). Dividing a tenth into 10 gives a hundredth (0.01).", "example": "0.7 means 7 tenths; 0.07 means 7 hundredths.", "dyk": "The decimal point separates the whole part from the fractional part.", "real": "Prices like ₹12.50 use decimals."}, {"icon": "📍", "title": "Place Value with Decimals", "text": "Places after the point are tenths, hundredths, thousandths and so on.", "example": "In 3.46, 4 is 4 tenths and 6 is 6 hundredths.", "dyk": "Each place is 10 times smaller than the place to its left.", "real": "Fuel meters show litres with decimals."}, {"icon": "📏", "title": "Units and Decimals", "text": "Smaller units can be written as decimals of bigger units.", "example": "15 mm = 1.5 cm; 250 g = 0.25 kg.", "dyk": "1 cm = 10 mm and 1 kg = 1000 g.", "real": "A doctor writes your height like 1.42 m."}, {"icon": "⚖️", "title": "Comparing Decimals", "text": "Compare the whole parts first, then tenths, then hundredths.", "example": "0.5 > 0.45 because 5 tenths > 4 tenths.", "dyk": "Adding zeros at the end does not change a decimal: 0.5 = 0.50.", "real": "Sports timings like 9.58 s and 9.63 s are compared this way."}, {"icon": "➕", "title": "Adding and Subtracting Decimals", "text": "Line up the decimal points, then add or subtract like whole numbers.", "example": "2.75 + 1.5 = 4.25.", "dyk": "Writing 1.5 as 1.50 helps keep places lined up.", "real": "Adding bills in rupees and paise uses decimal addition."}], "revision": {"terms": [["Tenth", "One part out of 10 equal parts (0.1)"], ["Hundredth", "One part out of 100 equal parts (0.01)"], ["Decimal point", "Separates whole part from fractional part"], ["Decimal place", "Position of a digit after the point"], ["Thousandth", "One part out of 1000 (0.001)"]], "facts": ["0.5 = 0.50 = 1/2.", "1 cm = 10 mm, so 1 mm = 0.1 cm.", "Line up decimal points while adding."]}, "summary": "Decimals extend place value beyond the point into tenths, hundredths and thousandths. They are used to write measurements in bigger units and money. Decimals are compared place by place from the left, and added or subtracted by lining up the decimal points."}, "c7maths_3": {"learn": [{"icon": "🔤", "title": "Letter-Numbers", "text": "A letter like n or x can stand for a number that can change or is unknown.", "example": "If a pen costs ₹p, then 3 pens cost ₹3p.", "dyk": "Using letters lets one rule work for many numbers.", "real": "Formulas in science use letters like d for distance."}, {"icon": "📐", "title": "Formulas", "text": "A formula is a rule written with letter-numbers.", "example": "Perimeter of a square with side s is 4s.", "dyk": "The same formula works for every square.", "real": "Builders use formulas to find areas of rooms."}, {"icon": "🧮", "title": "Finding the Value", "text": "Put a number in place of the letter to find the value of the expression.", "example": "If n = 5, then 2n + 3 = 13.", "dyk": "This is called substituting.", "real": "Finding the bill for any number of items uses substitution."}, {"icon": "🧩", "title": "Like Terms", "text": "Terms with the same letter part can be added or subtracted.", "example": "3a + 5a = 8a, but 3a + 5b cannot be combined.", "dyk": "Numbers alone, like 7, are constant terms.", "real": "Counting 3 boxes of a and 5 more boxes of a gives 8 boxes."}, {"icon": "🔁", "title": "Simplifying", "text": "Combine like terms to write an expression in a shorter form.", "example": "4x + 2 + 3x − 1 = 7x + 1.", "dyk": "Simplifying does not change the value for any number.", "real": "Shortened rules are easier to use and share."}], "revision": {"terms": [["Letter-number", "A letter that stands for a number"], ["Expression", "Combination of numbers, letters and operations"], ["Formula", "A general rule using letters"], ["Like terms", "Terms with the same letter part"], ["Substitution", "Putting a number in place of a letter"]], "facts": ["Perimeter of a square = 4s.", "3a + 5a = 8a.", "2n means 2 × n."]}, "summary": "Letters can represent numbers, which lets us write general rules called formulas. Expressions with letter-numbers can be evaluated by substituting values. Like terms can be combined to simplify expressions without changing their value."}, "c7maths_4": {"learn": [{"icon": "✖️", "title": "Intersecting Lines", "text": "Two lines that cross each other meet at one point and form four angles.", "example": "The two hands of scissors form intersecting lines.", "dyk": "At the point of intersection, the four angles add up to 360°.", "real": "Road crossings are examples of intersecting lines."}, {"icon": "🔄", "title": "Vertically Opposite Angles", "text": "When two lines intersect, the angles opposite each other are equal.", "example": "If one angle is 50°, the angle opposite it is also 50°.", "dyk": "Neighbouring angles at the crossing add up to 180°.", "real": "Carpenters use this to check cuts."}, {"icon": "➖", "title": "Linear Pair", "text": "Two adjacent angles on a straight line add up to 180°.", "example": "If one angle is 120°, the other is 60°.", "dyk": "A straight angle measures 180°.", "real": "A door opening forms a linear pair with the wall."}, {"icon": "🛤️", "title": "Parallel Lines", "text": "Lines on a plane that never meet, however far extended, are parallel.", "example": "Railway tracks and opposite edges of a ruler are parallel.", "dyk": "The distance between two parallel lines stays the same everywhere.", "real": "Notebook ruled lines are parallel."}, {"icon": "📐", "title": "Transversal and Angles", "text": "A line crossing two parallel lines is a transversal. Corresponding angles and alternate angles formed are equal.", "example": "If a corresponding angle is 70°, the matching angle is also 70°.", "dyk": "If corresponding angles are equal, the lines are parallel.", "real": "Zebra crossings show a transversal across parallel lines."}], "revision": {"terms": [["Intersecting lines", "Lines that cross at a point"], ["Vertically opposite angles", "Opposite angles at an intersection, always equal"], ["Linear pair", "Adjacent angles on a line adding to 180°"], ["Parallel lines", "Lines that never meet"], ["Transversal", "A line that crosses two or more lines"]], "facts": ["Vertically opposite angles are equal.", "A linear pair adds up to 180°.", "With parallel lines, corresponding angles are equal."]}, "summary": "When two lines intersect, vertically opposite angles are equal and adjacent angles form linear pairs that add up to 180°. Parallel lines never meet. A transversal crossing parallel lines makes equal corresponding angles and equal alternate angles."}, "c7maths_5": {"learn": [{"icon": "⚫", "title": "Parity: Even and Odd", "text": "Even + even = even, odd + odd = even, and even + odd = odd.", "example": "7 + 9 = 16 is even; 4 + 5 = 9 is odd.", "dyk": "The sum of an odd count of odd numbers is odd.", "real": "Pairing objects quickly tells if a count is odd or even."}, {"icon": "🔲", "title": "Magic Squares", "text": "In a magic square, every row, column and diagonal has the same sum, called the magic sum.", "example": "In a 3 × 3 magic square using 1 to 9, the magic sum is 15.", "dyk": "The centre of that square is always 5.", "real": "Magic squares appear in old Indian temples and books."}, {"icon": "🌀", "title": "Virahanka Numbers", "text": "Each number is the sum of the two before it: 1, 2, 3, 5, 8, 13, 21...", "example": "After 13 and 21 comes 34.", "dyk": "Virahanka described these numbers centuries before Fibonacci, while studying poetry rhythms.", "real": "They appear in flower petals and pinecone spirals."}, {"icon": "🔢", "title": "Digit Sums", "text": "Adding the digits of a number can reveal patterns, like divisibility by 3 and 9.", "example": "For 729, the digit sum is 18, so 729 is divisible by 9.", "dyk": "A number is divisible by 3 if its digit sum is divisible by 3.", "real": "Shopkeepers check bills using digit tricks."}, {"icon": "🧩", "title": "Grid Puzzles", "text": "Grid puzzles use parity and sums to find missing numbers.", "example": "If a row must sum to 12 and has 5 and 3, the missing number is 4.", "dyk": "Thinking about odd and even can rule out answers fast.", "real": "Sudoku-style puzzles use the same logic."}], "revision": {"terms": [["Parity", "Whether a number is even or odd"], ["Magic square", "Grid where all rows, columns and diagonals have the same sum"], ["Magic sum", "The common sum in a magic square"], ["Virahanka numbers", "Sequence where each term is the sum of the previous two"], ["Digit sum", "Sum of all digits of a number"]], "facts": ["odd + odd = even.", "3 × 3 magic square with 1 to 9 has magic sum 15.", "Divisible by 9 if the digit sum is divisible by 9."]}, "summary": "Number play explores patterns such as parity rules for adding even and odd numbers, magic squares where every line has the same sum, and Virahanka numbers where each term is the sum of the two before it. Digit sums help test divisibility and solve puzzles."}, "c7maths_6": {"learn": [{"icon": "🔺", "title": "Triangles", "text": "A triangle is formed by three line segments; it has 3 sides, 3 angles and 3 vertices.", "example": "Triangle ABC has sides AB, BC and CA.", "dyk": "The triangle is the strongest shape, which is why bridges use it.", "real": "Roof trusses use triangles for strength."}, {"icon": "📏", "title": "Types by Sides", "text": "Equilateral: all sides equal; isosceles: two sides equal; scalene: no sides equal.", "example": "A triangle with sides 5, 5 and 7 cm is isosceles.", "dyk": "Every equilateral triangle has all angles equal to 60°.", "real": "Road signs often use equilateral triangles."}, {"icon": "📐", "title": "Types by Angles", "text": "Acute: all angles less than 90°; right: one angle 90°; obtuse: one angle more than 90°.", "example": "Angles 30°, 60° and 90° make a right triangle.", "dyk": "A triangle can have only one right or one obtuse angle.", "real": "A set square is a right triangle."}, {"icon": "➕", "title": "Angle Sum Property", "text": "The three angles of any triangle add up to 180°.", "example": "If two angles are 50° and 60°, the third is 70°.", "dyk": "Tearing the corners of a paper triangle and joining them makes a straight line.", "real": "Surveyors use it to find unknown angles."}, {"icon": "⚖️", "title": "Triangle Inequality", "text": "The sum of any two sides of a triangle must be greater than the third side.", "example": "Sides 3, 4 and 8 cm cannot make a triangle because 3 + 4 < 8.", "dyk": "This helps check if a triangle is possible before drawing.", "real": "Shortest path rules in maps use this idea."}], "revision": {"terms": [["Triangle", "A closed shape with 3 sides"], ["Equilateral", "All three sides equal"], ["Isosceles", "Two sides equal"], ["Scalene", "No sides equal"], ["Angle sum property", "Angles of a triangle add to 180°"]], "facts": ["Angles of a triangle add up to 180°.", "Each angle of an equilateral triangle is 60°.", "Any two sides together must be longer than the third."]}, "summary": "A triangle is formed by three intersecting lines and has three sides, angles and vertices. Triangles are classified by sides (equilateral, isosceles, scalene) and by angles (acute, right, obtuse). The angles always add up to 180°, and any two sides together must be longer than the third."}, "c7maths_7": {"learn": [{"icon": "✖️", "title": "Multiplying Fractions", "text": "Multiply numerators together and denominators together.", "example": "2/3 × 3/4 = 6/12 = 1/2.", "dyk": "Simplify before multiplying to make numbers smaller.", "real": "Finding half of three-quarters of a pizza uses this."}, {"icon": "🍰", "title": "Fraction of a Quantity", "text": "To find a fraction of a number, multiply the number by the fraction.", "example": "3/4 of 20 = 15.", "dyk": "'Of' in fractions means multiply.", "real": "3/4 of ₹200 pocket money is ₹150."}, {"icon": "🔄", "title": "Reciprocal", "text": "The reciprocal of a/b is b/a. A number times its reciprocal is 1.", "example": "Reciprocal of 3/5 is 5/3; 3/5 × 5/3 = 1.", "dyk": "Zero has no reciprocal.", "real": "Reciprocals make division easy."}, {"icon": "➗", "title": "Dividing Fractions", "text": "To divide by a fraction, multiply by its reciprocal.", "example": "1/2 ÷ 1/4 = 1/2 × 4 = 2.", "dyk": "Dividing by a fraction less than 1 gives a bigger answer.", "real": "How many 1/4 kg packets from 2 kg of sugar? 2 ÷ 1/4 = 8."}, {"icon": "🧮", "title": "Product Size", "text": "Multiplying by a fraction less than 1 makes a number smaller; by more than 1 makes it bigger.", "example": "12 × 1/3 = 4, but 12 × 4/3 = 16.", "dyk": "This helps check if an answer makes sense.", "real": "Discounts work by multiplying prices by a fraction."}], "revision": {"terms": [["Numerator", "Top number of a fraction"], ["Denominator", "Bottom number of a fraction"], ["Reciprocal", "Fraction turned upside down"], ["Product", "Result of multiplication"], ["Proper fraction", "Numerator smaller than denominator"]], "facts": ["a/b × c/d = (a × c)/(b × d).", "a/b ÷ c/d = a/b × d/c.", "A number × its reciprocal = 1."]}, "summary": "Fractions are multiplied by multiplying numerators and denominators. Finding a fraction of a quantity means multiplying. To divide by a fraction, multiply by its reciprocal. Multiplying by a fraction less than one makes a number smaller, while dividing by it makes the number bigger."}, "c7maths_8": {"learn": [{"icon": "👯", "title": "Congruent Figures", "text": "Figures with exactly the same shape and size are congruent. One fits exactly on the other.", "example": "Two ₹10 coins of the same type are congruent.", "dyk": "The symbol ≅ means 'is congruent to'.", "real": "Machine-made parts like bottle caps are congruent."}, {"icon": "🔺", "title": "Congruent Triangles", "text": "Two triangles are congruent if their matching sides and angles are all equal.", "example": "If △ABC ≅ △PQR, then AB = PQ and ∠A = ∠P.", "dyk": "Matching parts are called corresponding parts.", "real": "Bridge trusses use congruent triangles for balance."}, {"icon": "📏", "title": "SSS Rule", "text": "If three sides of one triangle equal three sides of another, the triangles are congruent.", "example": "Triangles with sides 3, 4, 5 cm and 4, 5, 3 cm are congruent.", "dyk": "SSS means Side-Side-Side.", "real": "A triangle frame with fixed sides cannot change shape."}, {"icon": "📐", "title": "SAS and ASA Rules", "text": "SAS: two sides and the angle between them are equal. ASA: two angles and the side between them are equal.", "example": "AB = PQ, ∠B = ∠Q, BC = QR gives △ABC ≅ △PQR by SAS.", "dyk": "The angle in SAS must be the one between the two sides.", "real": "Surveyors use ASA to measure distances across rivers."}, {"icon": "⬛", "title": "RHS Rule", "text": "In right triangles, if the hypotenuse and one side are equal, the triangles are congruent.", "example": "Two right triangles with hypotenuse 10 cm and a side 6 cm are congruent.", "dyk": "RHS means Right angle-Hypotenuse-Side.", "real": "Ladders leaning the same way on a wall make congruent right triangles."}], "revision": {"terms": [["Congruent", "Same shape and same size"], ["Corresponding parts", "Matching sides and angles"], ["SSS", "Side-Side-Side rule"], ["SAS", "Two sides and included angle"], ["RHS", "Right angle, hypotenuse and a side"]], "facts": ["≅ means congruent.", "SSS, SAS, ASA and RHS prove triangles congruent.", "AAA does not prove congruence."]}, "summary": "Congruent figures have the same shape and size. Two triangles are congruent when their corresponding sides and angles match, which can be shown using the SSS, SAS, ASA or RHS rules. Equal angles alone (AAA) only show the same shape, not the same size."}, "c7maths_9": {"learn": [{"icon": "➕", "title": "Adding Integers", "text": "Adding a positive number moves right on the number line; adding a negative number moves left.", "example": "(−5) + 3 = −2; (−4) + (−6) = −10.", "dyk": "Numbers like 7 and −7 add up to 0; they are additive inverses.", "real": "Bank deposits and withdrawals work like adding integers."}, {"icon": "➖", "title": "Subtracting Integers", "text": "Subtracting an integer is the same as adding its opposite.", "example": "5 − (−3) = 5 + 3 = 8.", "dyk": "Subtracting a negative number makes the answer bigger.", "real": "Temperature change from −2°C to 6°C is 6 − (−2) = 8 degrees."}, {"icon": "✖️", "title": "Multiplying Integers", "text": "Same signs give a positive product; different signs give a negative product.", "example": "(−6) × (−3) = 18; (−6) × 3 = −18.", "dyk": "Any integer multiplied by 0 is 0.", "real": "Losing ₹20 each day for 5 days is (−20) × 5 = −100."}, {"icon": "➗", "title": "Dividing Integers", "text": "Division follows the same sign rules as multiplication.", "example": "(−20) ÷ 4 = −5; (−20) ÷ (−4) = 5.", "dyk": "Division by 0 is not defined.", "real": "Sharing a loss equally uses integer division."}, {"icon": "🔁", "title": "Properties", "text": "Integers are closed under addition, subtraction and multiplication. Addition and multiplication are commutative and associative.", "example": "(−3) + 7 = 7 + (−3) = 4.", "dyk": "Subtraction and division are not commutative.", "real": "Grouping smartly makes mental calculation easier."}], "revision": {"terms": [["Integer", "Whole numbers and their negatives, including 0"], ["Additive inverse", "The opposite number, e.g. −7 for 7"], ["Product", "Result of multiplication"], ["Quotient", "Result of division"], ["Closure", "Result stays an integer"]], "facts": ["(−) × (−) = (+).", "(−) × (+) = (−).", "a − b = a + (−b)."]}, "summary": "Integers include positive numbers, negative numbers and zero. Adding a negative moves left on the number line, and subtracting means adding the opposite. For multiplication and division, same signs give a positive answer and different signs give a negative answer. Division by zero is not defined."}, "c7maths_10": {"learn": [{"icon": "🧱", "title": "Common Factors", "text": "Factors shared by two or more numbers are their common factors.", "example": "Factors of 12: 1, 2, 3, 4, 6, 12. Factors of 16: 1, 2, 4, 8, 16. Common: 1, 2, 4.", "dyk": "1 is a common factor of every pair of numbers.", "real": "Cutting two ribbons into equal pieces uses common factors."}, {"icon": "🏆", "title": "HCF", "text": "The Highest Common Factor (HCF) is the greatest number that divides all the given numbers.", "example": "HCF of 12 and 16 is 4.", "dyk": "If the HCF is 1, the numbers are called co-prime.", "real": "Finding the largest square tile for a floor uses HCF."}, {"icon": "🔁", "title": "Common Multiples", "text": "Multiples shared by two numbers are their common multiples.", "example": "Multiples of 6: 6, 12, 18, 24... Multiples of 8: 8, 16, 24... Common: 24, 48...", "dyk": "Common multiples go on forever.", "real": "Two buses meeting again at a stop is about common multiples."}, {"icon": "🎯", "title": "LCM", "text": "The Lowest Common Multiple (LCM) is the smallest common multiple.", "example": "LCM of 6 and 8 is 24.", "dyk": "For two numbers, HCF × LCM = product of the numbers.", "real": "Planning when two events repeat together uses LCM."}, {"icon": "🌳", "title": "Prime Factorisation", "text": "Breaking numbers into primes helps find HCF and LCM quickly.", "example": "45 = 3 × 3 × 5, 75 = 3 × 5 × 5. HCF = 3 × 5 = 15.", "dyk": "Every number has exactly one prime factorisation.", "real": "Computers use prime factors to keep messages safe."}], "revision": {"terms": [["Factor", "A number that divides another exactly"], ["Multiple", "Result of multiplying a number by 1, 2, 3, ..."], ["HCF", "Greatest common factor"], ["LCM", "Smallest common multiple"], ["Co-prime", "Numbers whose HCF is 1"]], "facts": ["HCF × LCM = product of two numbers.", "HCF of co-prime numbers is 1.", "LCM is always a multiple of each number."]}, "summary": "Common factors are factors shared by numbers, and the greatest of them is the HCF. Common multiples are shared multiples, and the smallest is the LCM. Prime factorisation is a reliable way to find both. For two numbers, HCF × LCM equals their product."}, "c7maths_11": {"learn": [{"icon": "✖️", "title": "Multiplying by 10, 100, 1000", "text": "Multiplying a decimal by 10, 100 or 1000 moves the decimal point 1, 2 or 3 places to the right.", "example": "3.45 × 100 = 345.", "dyk": "Dividing moves the point to the left: 3.45 ÷ 10 = 0.345.", "real": "Converting metres to centimetres multiplies by 100."}, {"icon": "🔢", "title": "Decimal × Whole Number", "text": "Multiply as whole numbers, then put the same number of decimal places as in the decimal.", "example": "1.25 × 4 = 5.00 = 5.", "dyk": "Estimating first helps place the decimal point.", "real": "Price of 4 pens at ₹12.50 each is ₹50."}, {"icon": "🧮", "title": "Decimal × Decimal", "text": "Multiply as whole numbers; decimal places in the answer = total decimal places in both numbers.", "example": "0.3 × 0.2 = 0.06.", "dyk": "Multiplying by a decimal less than 1 makes the number smaller.", "real": "Area of a 1.5 m × 0.8 m table = 1.2 sq m."}, {"icon": "➗", "title": "Dividing Decimals", "text": "To divide by a decimal, shift both points the same number of places to make the divisor a whole number.", "example": "1.2 ÷ 0.4 = 12 ÷ 4 = 3.", "dyk": "Dividing by a decimal less than 1 gives a bigger answer.", "real": "How many 0.25 L glasses from 2 L of juice? 2 ÷ 0.25 = 8."}, {"icon": "📏", "title": "Decimals and Measurement", "text": "Decimals let us convert units and compare measurements precisely.", "example": "2.5 kg = 2500 g; 0.75 m = 75 cm.", "dyk": "1 m = 100 cm and 1 km = 1000 m.", "real": "Shopkeepers weigh vegetables in decimals of a kilogram."}], "revision": {"terms": [["Decimal place", "Position of a digit after the point"], ["Product", "Result of multiplication"], ["Quotient", "Result of division"], ["Divisor", "Number by which we divide"], ["Estimation", "Rounding to check an answer"]], "facts": ["× 100 moves the point 2 places right.", "0.3 × 0.2 = 0.06.", "1.2 ÷ 0.4 = 3."]}, "summary": "Multiplying decimals by 10, 100 or 1000 moves the decimal point to the right, and dividing moves it left. When multiplying decimals, count the total decimal places. To divide by a decimal, shift the decimal points to make the divisor a whole number. Decimals help convert and compare measurements."}, "c7maths_12": {"learn": [{"icon": "📊", "title": "Statistical Questions", "text": "A statistical question expects answers that vary, so we collect data to answer it.", "example": "'How many hours do students in my class sleep?' is statistical.", "dyk": "'How old am I?' is not statistical because it has one answer.", "real": "Schools collect data to plan lunch menus."}, {"icon": "⚖️", "title": "Mean (Average)", "text": "Mean = sum of all values ÷ number of values. It is the 'fair share' value.", "example": "Mean of 8, 10, 6, 12 and 9 = 45 ÷ 5 = 9.", "dyk": "The mean always lies between the smallest and largest values.", "real": "A batsman's average uses the mean."}, {"icon": "📍", "title": "Median", "text": "The median is the middle value when data is arranged in order. For an even count, it is the mean of the two middle values.", "example": "Median of 3, 5, 5, 7, 8, 9 = (5 + 7) ÷ 2 = 6.", "dyk": "Half the values are below the median and half above.", "real": "House prices are often reported using the median."}, {"icon": "🚩", "title": "Outliers", "text": "An outlier is a value far away from the rest. It can change the mean a lot but barely changes the median.", "example": "In 5, 6, 6, 7, 31, the median is 6 but the mean is 11.", "dyk": "When outliers exist, the median often describes data better.", "real": "One very rich person can make an area's average income look high."}, {"icon": "🔵", "title": "Dot Plots", "text": "A dot plot shows each data value as a dot above a number line, making patterns easy to see.", "example": "Marks of 10 students can be shown as dots above 0 to 10.", "dyk": "Dot plots quickly show clusters and outliers.", "real": "Coaches use them to see how players score."}], "revision": {"terms": [["Data", "Collected facts or numbers"], ["Mean", "Sum of values divided by their count"], ["Median", "Middle value of ordered data"], ["Outlier", "A value far from the rest"], ["Dot plot", "Dots above a number line showing data"]], "facts": ["Mean = sum ÷ count.", "Median is the middle value of ordered data.", "Outliers affect the mean more than the median."]}, "summary": "Statistics helps answer questions whose answers vary. The mean is the sum of values divided by their count, and the median is the middle value of ordered data. Outliers can pull the mean far away while the median stays steady. Dot plots help us see data, means and medians at a glance."}, "c7maths_13": {"learn": [{"icon": "🧭", "title": "Compass and Ruler", "text": "A compass draws circles and arcs; a ruler draws straight lines. Together they make exact constructions.", "example": "An arc of radius 4 cm marks all points 4 cm from the centre.", "dyk": "Constructions do not use a protractor for measuring.", "real": "Architects began with compass-and-ruler drawings."}, {"icon": "⊥", "title": "Perpendicular Bisector", "text": "The perpendicular bisector of a segment cuts it into two equal halves at 90°.", "example": "Arcs from both ends of AB meet at two points; joining them bisects AB.", "dyk": "Every point on the perpendicular bisector is equally far from both ends.", "real": "Finding the middle of a plank uses this idea."}, {"icon": "🔺", "title": "Constructing Triangles", "text": "A triangle can be drawn from three sides (SSS), two sides and the included angle (SAS), or two angles and a side (ASA).", "example": "For sides 5, 6 and 7 cm, draw one side and use arcs for the other two.", "dyk": "Sides must satisfy the triangle inequality, or no triangle forms.", "real": "Engineers mark triangular supports this way."}, {"icon": "🧩", "title": "Tilings", "text": "A tiling covers a flat surface with shapes without gaps or overlaps.", "example": "Squares, equilateral triangles and regular hexagons can tile a floor alone.", "dyk": "Angles meeting at a point in a tiling add up to 360°.", "real": "Honeycombs use hexagonal tiling."}, {"icon": "⬡", "title": "Why Some Shapes Tile", "text": "A regular polygon tiles alone only if its angle divides 360° exactly.", "example": "Hexagon angle 120°: 3 × 120° = 360°, so it tiles.", "dyk": "A regular pentagon (108°) cannot tile alone.", "real": "Floor and wall tiles are chosen using this rule."}], "revision": {"terms": [["Compass", "Tool to draw circles and arcs"], ["Arc", "Part of a circle"], ["Perpendicular bisector", "Line cutting a segment in half at 90°"], ["Tiling", "Covering a surface without gaps or overlaps"], ["Regular polygon", "All sides and angles equal"]], "facts": ["Angles around a point add up to 360°.", "Squares, equilateral triangles and regular hexagons tile alone.", "Perpendicular bisector meets the segment at 90°."]}, "summary": "Using only a compass and ruler, we can construct perpendicular bisectors and triangles from given sides and angles. Tilings cover a surface with shapes leaving no gaps or overlaps. A regular polygon tiles by itself only if its interior angle divides 360° exactly, which is true for triangles, squares and hexagons."}, "c7maths_14": {"learn": [{"icon": "❓", "title": "Equations", "text": "An equation says two expressions are equal and often has an unknown, like x + 5 = 12.", "example": "In x + 5 = 12, x = 7.", "dyk": "An equation is like a balanced weighing scale.", "real": "Finding the price of one item from a total bill uses equations."}, {"icon": "⚖️", "title": "Balancing", "text": "Do the same operation on both sides to keep the equation balanced.", "example": "x − 4 = 10 → add 4 to both sides → x = 14.", "dyk": "Undoing an operation uses its opposite: + undoes −, × undoes ÷.", "real": "A balanced see-saw stays level when equal weights are added."}, {"icon": "✖️", "title": "Solving with Multiplication", "text": "If a number is multiplied by x, divide both sides by that number.", "example": "3x = 21 → x = 7.", "dyk": "Always check the answer by putting it back in the equation.", "real": "If 3 tickets cost ₹21, one costs ₹7."}, {"icon": "🧮", "title": "Two-Step Equations", "text": "Undo addition or subtraction first, then multiplication or division.", "example": "2x + 3 = 15 → 2x = 12 → x = 6.", "dyk": "Working step by step avoids mistakes.", "real": "Phone plans with a fixed fee plus a rate use two-step equations."}, {"icon": "📝", "title": "Word Problems", "text": "Turn the story into an equation using a letter for the unknown, then solve.", "example": "Think of a number, add 9, get 25: x + 9 = 25, so x = 16.", "dyk": "Writing what x stands for keeps the meaning clear.", "real": "Age puzzles are solved with equations."}], "revision": {"terms": [["Equation", "Statement that two expressions are equal"], ["Unknown", "The letter whose value we find"], ["Solution", "Value that makes the equation true"], ["Balance", "Doing the same to both sides"], ["Check", "Putting the answer back to verify"]], "facts": ["Do the same operation on both sides.", "Undo + with −, and × with ÷.", "Check the solution by substituting."]}, "summary": "An equation states that two expressions are equal and often contains an unknown. We solve it by doing the same operation on both sides, undoing operations step by step until the unknown is alone. Word problems become equations by letting a letter stand for the unknown, and every solution can be checked by substitution."}};
